const https = require('https');

// Create connection pool
const agent = new https.Agent({
  keepAlive: true,
  maxSockets: 50,
  maxFreeSockets: 10,
  timeout: 60000,
});

// Use agent for requests
fetch('https://api.example.com/data', { agent });

const resources = performance.getEntriesByType('resource');

resources.forEach(resource => {
  const duration = resource.duration;
  const transferSize = resource.transferSize;
  const encodedSize = resource.encodedSize;

  console.log(`${resource.name}:`);
  console.log(`  Duration: ${duration.toFixed(2)}ms`);
  console.log(`  Transfer size: ${(transferSize / 1024).toFixed(2)}KB`);
  console.log(`  Compression ratio: ${((1 - transferSize / encodedSize) * 100).toFixed(1)}%`);

  // Identify slow resources
  if (duration > 1000) {
    console.warn('Slow resource detected:', resource.name);
  }
});
